reference_solution:
def first_valid_adjacent_digit_pair(s):
    from collections import Counter
    counts=Counter(s)
    for left,right in zip(s,s[1:]):
        if left!=right and counts[left]==int(left) and counts[right]==int(right):return left+right
    return ''

